package gen

import (
	"bytes"
	"fmt"
	"path"
	"slices"
	"sort"
	"strings"
)

// rubyMetadataField is the field name the Ruby message metadata accessor,
// GrpcServiceMesh::Metadata#mesh_metadata, takes on every rpc message class.
const rubyMetadataField = "mesh_metadata"

func rubyKind(k Kind) string {
	if k == Topic {
		return ":topic"
	}
	return ":route"
}

// rubyRequire returns the require line that loads the message file of m from
// a generated file in directory dir.
func rubyRequire(dir string, m MessageRef) string {
	p := rubyRequirePath(m.File)
	if path.Dir(m.File) == dir {
		return fmt.Sprintf("require_relative %s", rubyString(path.Base(p)))
	}
	return fmt.Sprintf("require %s", rubyString(p))
}

// RubyFile renders the directory's <dir>_grpcmesh.rb. After the services it
// includes GrpcServiceMesh::Metadata into every message class an rpc of the
// directory takes or returns.
func RubyFile(d Directory) (string, []byte, error) {
	requires := map[string]bool{}
	includes := map[string]bool{}
	for _, s := range d.Services {
		for _, m := range s.Methods {
			for _, msg := range []MessageRef{m.Input, m.Output} {
				if slices.Contains(msg.FieldNames, rubyMetadataField) {
					return "", nil, fmt.Errorf("%s: %s declares a field named %s, which the Ruby message metadata accessor hides", msg.File, msg.FullName, rubyMetadataField)
				}
				requires[rubyRequire(d.Path, msg)] = true
				includes[fmt.Sprintf("::%s.include(GrpcServiceMesh::Metadata)", rubyMessageName(msg))] = true
			}
		}
	}
	var external, relative []string
	for r := range requires {
		if strings.HasPrefix(r, "require_relative") {
			relative = append(relative, r)
		} else {
			external = append(external, r)
		}
	}
	sort.Strings(external)
	sort.Strings(relative)

	var b bytes.Buffer
	b.WriteString("# frozen_string_literal: true\n\n")
	b.WriteString("# Generated by grpc-service-mesh-gen. DO NOT EDIT.\n")
	for _, f := range d.SourceFiles() {
		fmt.Fprintf(&b, "# source: %s\n", f)
	}
	fmt.Fprintf(&b, "# transport: %s\n\n", d.Transport)
	b.WriteString("require \"grpc_service_mesh\"\n")
	for _, r := range external {
		b.WriteString(r + "\n")
	}
	for _, r := range relative {
		b.WriteString(r + "\n")
	}

	// Services grouped by module, in order of first appearance.
	var order []string
	groups := map[string][]Service{}
	for _, s := range d.Services {
		mod := rubyModule(s.Package, s.RubyPackage)
		if _, ok := groups[mod]; !ok {
			order = append(order, mod)
		}
		groups[mod] = append(groups[mod], s)
	}
	for _, mod := range order {
		mods := strings.Split(mod, "::")
		b.WriteString("\n")
		for i, m := range mods {
			fmt.Fprintf(&b, "%smodule %s\n", strings.Repeat("  ", i), m)
		}
		indent := strings.Repeat("  ", len(mods))
		for i, s := range groups[mod] {
			if i > 0 {
				b.WriteString("\n")
			}
			rubyService(&b, indent, d, s)
		}
		for i := len(mods) - 1; i >= 0; i-- {
			fmt.Fprintf(&b, "%send\n", strings.Repeat("  ", i))
		}
	}

	lines := make([]string, 0, len(includes))
	for l := range includes {
		lines = append(lines, l)
	}
	sort.Strings(lines)
	b.WriteString("\n")
	for _, l := range lines {
		b.WriteString(l + "\n")
	}
	return path.Join(d.Path, path.Base(d.Path)+"_grpcmesh.rb"), b.Bytes(), nil
}

func rubyService(b *bytes.Buffer, indent string, d Directory, s Service) {
	base := upperFirst(BaseName(s.Name))
	targets, client, service := base+"Targets", base+"Client", upperFirst(s.Name)
	segments := append(strings.Split(s.Package, "."), s.Name)

	fmt.Fprintf(b, "%smodule %s\n", indent, targets)
	for _, m := range s.Methods {
		var segs []string
		for _, seg := range append(append([]string{}, segments...), m.Name) {
			segs = append(segs, rubyString(seg))
		}
		md := []string{fmt.Sprintf("\"transport\" => %s", rubyString(d.Transport))}
		fmt.Fprintf(b, "%s  %s = ServiceMesh::Target.new(\n", indent, ScreamingSnake(SnakeCase(m.Name)))
		fmt.Fprintf(b, "%s    segments: [%s],\n", indent, strings.Join(segs, ", "))
		fmt.Fprintf(b, "%s    kind: %s,\n", indent, rubyKind(m.Kind))
		fmt.Fprintf(b, "%s    metadata: {%s}\n", indent, strings.Join(md, ", "))
		fmt.Fprintf(b, "%s  )\n", indent)
	}
	fmt.Fprintf(b, "%send\n", indent)

	for _, cls := range []struct{ name, parent string }{
		{service, "GrpcServiceMesh::RPCService"},
		{client, "GrpcServiceMesh::RPCClient"},
	} {
		fmt.Fprintf(b, "\n%sclass %s < %s\n", indent, cls.name, cls.parent)
		for _, m := range s.Methods {
			fmt.Fprintf(b, "%s  rpc :%s, target: %s::%s, input: %s", indent, SnakeCase(m.Name), targets, ScreamingSnake(SnakeCase(m.Name)), rubyMessageName(m.Input))
			if m.Kind == Route {
				fmt.Fprintf(b, ", output: %s", rubyMessageName(m.Output))
			}
			fmt.Fprintf(b, ", kind: %s", rubyKind(m.Kind))
			if cls.name == service && m.ConsumerGroup != "" {
				fmt.Fprintf(b, ", consumer_group: %s", rubyString(m.ConsumerGroup))
			}
			b.WriteString("\n")
		}
		fmt.Fprintf(b, "%send\n", indent)
	}
}

// RubyServiceMaps renders service_maps.rb, one constant per transport.
func RubyServiceMaps(m *Model) (string, []byte, error) {
	var b bytes.Buffer
	b.WriteString("# frozen_string_literal: true\n\n")
	b.WriteString("# Generated by grpc-service-mesh-gen. DO NOT EDIT.\n")
	b.WriteString("# One ServiceMap per transport, holding every Target served over it.\n\n")
	b.WriteString("require \"service_mesh\"\n")
	for _, d := range m.Directories {
		fmt.Fprintf(&b, "require_relative %s\n", rubyString(path.Join(d.Path, path.Base(d.Path)+"_grpcmesh")))
	}
	b.WriteString("\nmodule ServiceMaps\n")
	for i, t := range m.Transports() {
		if i > 0 {
			b.WriteString("\n")
		}
		var refs []string
		for _, d := range m.Directories {
			if d.Transport != t {
				continue
			}
			for _, s := range d.Services {
				mod := rubyModule(s.Package, s.RubyPackage)
				for _, mt := range s.Methods {
					refs = append(refs, fmt.Sprintf("    %s::%sTargets::%s", mod, upperFirst(BaseName(s.Name)), ScreamingSnake(SnakeCase(mt.Name))))
				}
			}
		}
		fmt.Fprintf(&b, "  %s = ServiceMesh::ServiceMap.new(targets: [\n", ScreamingSnake(t))
		b.WriteString(strings.Join(refs, ",\n"))
		if len(refs) > 0 {
			b.WriteString("\n")
		}
		b.WriteString("  ])\n")
	}
	b.WriteString("end\n")
	return "service_maps.rb", b.Bytes(), nil
}
